from collections import Counter
docs = [["search", "index"], ["search", "cache"], ["index", "cache"], ["search", "index"]]
pairs = Counter()
for d in docs:
    for i in range(len(d)):
        for j in range(i + 1, len(d)):
            pairs[tuple(sorted((d[i], d[j])))] += 1
for p, n in pairs.most_common(2):
    print(p, "co-occur in", n, "records")

